oxy_webhelp_navlinks = {"ad_protection-d39536e58281":{"topics":[{"title":"Active Directory forest","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Rubrik Security Cloud<\/span> offers protection services for the Active Directory forest         hierarchy. You can protect and recover the entire forest hierarchy in the event of a         disaster or ransomware attack.<\/p>","href":"adds\/active_directory_forest.html","attributes":{"data-id":"active_directory_forest"},"menu":{"hasChildren":false},"tocID":"active_directory_forest-d39536e58294","next":"active_directory_forest-d39536e58294"},{"title":"Active Directory domains and domain controllers","shortdesc":"<p class=\"shortdesc\">You can protect and recover Active Directory domains and domain controllers by using         the protection services offered by <span class=\"ph\">Rubrik Security Cloud<\/span>.<\/p>","href":"adds\/active_directory_domain_dc.html","attributes":{"data-id":"active_directory_domain_dc"},"menu":{"hasChildren":false},"tocID":"active_directory_domain_dc-d39536e58620","next":"active_directory_domain_dc-d39536e58620"},{"title":"Troubleshooting AD recovery scenarios","href":"adds\/dynamic_disk_foreign_state_dc.html","menu":{"hasChildren":false},"tocID":"tocId-d39536e59042","next":"tocId-d39536e59042"},{"title":"Quorum authorization for Active Directory","shortdesc":"<p class=\"shortdesc\">Quorum Authorization protects Active Directory operations by requiring multi-user         approval before an administrator can run an action, preventing a single administrator from         unilaterally performing destructive or high-impact tasks.<\/p>","href":"adds\/ad_qauth.html","attributes":{"data-id":"ad_qauth"},"menu":{"hasChildren":false},"tocID":"ad_qauth-d39536e59123","topics":[]}]}};